using Companion.Core.Services;
using Companion.Infrastructure.Models;

namespace Companion.Eval;

/// <summary>
/// Truth tables for the decisions that are pure functions of a single message.
///
/// These are the cheapest evaluable things in the codebase — no store, no models, no I/O, so a
/// hundred thousand cases cost a second — and until now they had no evidence at all. The Phase Gate
/// could say nothing about tool routing or completion detection because nothing had ever measured
/// them, which is a worse position than measuring them badly.
///
/// Cases are generated by crossing templates with fillers rather than written out, so the table
/// grows by adding a phrasing rather than by adding a hundred lines. The label comes from which
/// bucket a template was declared in, which is the same discipline as the lives generator: the
/// expected answer is fixed before the function is asked.
///
/// The hard negatives are the point. Anyone can write cases a keyword list gets right; these are
/// deliberately built so that the wrong answer is the tempting one — a message that mentions
/// writing without asking for any, a reply that ends mid-sentence after a full stop, a question
/// about capability that is really about the weather.
/// </summary>
public static class TextTruthTables
{
    /// <summary>One generated case: what was said, and what the answer must be.</summary>
    private sealed record Case(string Text, bool Expected, string Family);

    // ---- CompletionSignals.IsDeliverableRequest ------------------------------------------------
    // Did the user ask for a produced artifact, or merely talk about one? Getting this wrong put an
    // ordinary conversational turn on the auto-continuation path, where a completion judge ran it
    // five times and returned four answers.

    private static readonly string[] Deliverables =
    {
        "write me {a}", "draft {a}", "can you put together {a}", "could you write {a}",
        "give me {a}", "make me {a}", "please write {a}", "I need you to draft {a}",
        "walk me through {a} step by step", "list the steps for {a}",
    };

    private static readonly string[] SelfReports =
    {
        "I'm writing {a}", "I've been drafting {a}", "I wrote {a} last week",
        "we're planning {a}", "I built {a} myself", "I'm working on {a} at the moment",
        "I finished {a} yesterday", "I've nearly finished {a}",
    };

    private static readonly string[] Conversation =
    {
        "how's your day been", "that's a relief", "morning", "I slept badly",
        "the trains were awful again", "what do you make of that", "thanks, that helps",
    };

    private static readonly string[] Objects =
    {
        "a talk on soil chemistry", "an email to my landlord", "a plan for the week",
        "a story about a lighthouse", "the shed roof", "a summary of the meeting",
    };

    // ---- CompletionSignals.LooksUnfinished -----------------------------------------------------

    private static readonly string[] Unfinished =
    {
        "The three things to check are:", "Start with the header tank and then",
        "```csharp\nvar x = 1;", "Would you like me to continue?",
        "I'd begin by checking the solenoid, because",
    };

    private static readonly string[] Finished =
    {
        "Start with the header tank, then the solenoid.", "That should do it.",
        "Hope that helps!", "I'd check the solenoid first — they fail more often than timers.",
        "Good luck with it 🙂",
    };

    // ---- ToolNudge.Detect ----------------------------------------------------------------------

    private static readonly string[] CapabilityQuestions =
    {
        "what can you actually do", "are you able to see images", "can you hear me",
        "what do you do exactly", "are you capable of reading files",
    };

    private static readonly string[] NotCapability =
    {
        "what can you see from your window", "can you believe this weather",
        "are you able to come tomorrow", "what do you think I should do",
        "can you tell my sister I said hello",
    };

    public static int Run(bool verbose)
    {
        var results = new List<Metrics>
        {
            Score("deliverable-request", DeliverableCases(),
                c => CompletionSignals.IsDeliverableRequest(c.Text), verbose),
            Score("looks-unfinished", CompletionCases(),
                c => CompletionSignals.LooksUnfinished(c.Text), verbose),
            Score("capability-nudge", NudgeCases(),
                c => ToolNudge.Detect(c.Text) is not null, verbose),
        };

        Console.WriteLine();
        foreach (var m in results)
            Console.WriteLine(m.ToLine());

        Console.WriteLine();
        Console.WriteLine($"{results.Sum(m => m.Total)} generated cases, no models, no store");
        return 0;
    }

    private static IEnumerable<Case> DeliverableCases()
    {
        foreach (var o in Objects)
        {
            foreach (var t in Deliverables)
                yield return new Case(t.Replace("{a}", o), true, "asked for");
            // Hard negatives: the same nouns and the same verbs, with the user doing the work.
            foreach (var t in SelfReports)
                yield return new Case(t.Replace("{a}", o), false, "self-reported");
            // …and the same self-report with a request bolted on, which IS a deliverable.
            foreach (var t in SelfReports.Take(3))
                yield return new Case($"{t.Replace("{a}", o)} — can you help me finish it?", true, "asked for");
        }
        foreach (var c in Conversation)
            yield return new Case(c, false, "conversation");
    }

    private static IEnumerable<Case> CompletionCases()
    {
        foreach (var u in Unfinished)
            yield return new Case(u, true, "unfinished");
        foreach (var f in Finished)
            yield return new Case(f, false, "finished");
    }

    private static IEnumerable<Case> NudgeCases()
    {
        foreach (var q in CapabilityQuestions)
            yield return new Case(q, true, "capability");
        foreach (var q in NotCapability)
            yield return new Case(q, false, "not capability");
    }

    private static Metrics Score(
        string name, IEnumerable<Case> cases, Func<Case, bool> predict, bool verbose)
    {
        var rows = cases.ToList();
        var results = new List<(bool, bool)>(rows.Count);
        foreach (var c in rows)
        {
            var got = predict(c);
            results.Add((c.Expected, got));
            if (verbose && got != c.Expected)
                Console.WriteLine($"     {(c.Expected ? "missed " : "false +")} [{c.Family}] {c.Text}");
        }
        return Metrics.From(name, results);
    }
}
